class Solution:
    def smallestPalindrome(self, s: str) -> str:
        cnt = [0] * 26
        for c in s:
            cnt[ord(c) - ord('a')] += 1

        half = []
        mid = ''
        for i in range(26):
            c = chr(ord('a') + i)
            half.append(c * (cnt[i] // 2))
            if cnt[i] % 2 == 1:
                mid = c

        left = ''.join(half)
        return left + mid + left[::-1]
